        "content": "import sys\nimport display_driver\nimport lvgl as lv\nif (display_driver.WIDTH, display_driver.HEIGHT) != (1024, 600):\n    raise RuntimeError('UI requires 1024x600')\nAPP_DIR = __file__.rsplit('/', 1)[0] if '/' in __file__ else '.'\nif APP_DIR not in sys.path:\n    sys.path.insert(0, APP_DIR)\nimport ui\nimport app_events\n\nui.screens = [None] * 2\nui.screens[0] = lv.obj()\nui.c64_keyboard_create_keyboard(ui.screens[0])\nui.screens[1] = lv.obj()\nui.c64_keyboard_create_setup(ui.screens[1])\nui.screens[0].add_event_cb(app_events.keyboard_screen_loaded, lv.EVENT.SCREEN_LOADED, None)\nui.screens[1].add_event_cb(app_events.setup_screen_loaded, lv.EVENT.SCREEN_LOADED, None)\nui.btn_setup.add_event_cb(app_events.btn_setup_clicked, lv.EVENT.CLICKED, None)\nui.btn_clear.add_event_cb(app_events.btn_clear_clicked, lv.EVENT.CLICKED, None)\nui.btn_save.add_event_cb(app_events.btn_save_clicked, lv.EVENT.CLICKED, None)\nui.btn_test.add_event_cb(app_events.btn_test_clicked, lv.EVENT.CLICKED, None)\nui.btn_back.add_event_cb(app_events.btn_back_clicked, lv.EVENT.CLICKED, None)\nlv.screen_load(ui.screens[0])\nui.current_screen = 0\ndisplay_driver.start()\nprint('LMS_APP_READY buffers=%s touch=%s' % (display_driver.BUFFERS, display_driver.indev is not None))\n"
